{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    node_index = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)
    edges = []
    for u, v, d in distances:
        w = max(core[u], core[v], d)
        if u > v:
            u, v = v, u
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(node_index[u], node_index[v]):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    return {'edges': mst_edges, 'total_weight': total_weight}"
